starterCode.css:
body { margin: 0; font-family: system-ui, sans-serif; background: #f7fafc; }
.toolbar { padding: 16px; border-bottom: 1px solid #d8e0ea; background: white; }
h1 { margin: 0; font-size: 1.25rem; }
button { border: 1px solid #c8d2df; background: #f8fafc; border-radius: 6px; padding: 8px 12px; }

targetCode.css:
body { margin: 0; font-family: system-ui, sans-serif; background: #f7fafc; }
.toolbar { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 12px; padding: 16px; border-bottom: 1px solid #d8e0ea; background: white; }
h1 { margin: 0; font-size: 1.25rem; }
.acciones { display: flex; gap: 8px; flex-wrap: wrap; }
button { border: 1px solid #c8d2df; background: #f8fafc; border-radius: 6px; padding: 8px 12px; }
